// ============================================================================
// NOTIFICATIONS PAGE — the inbox that the database writes.
//
// Nothing on this page is generated by the browser: every row comes from
// GET /api/notifications, which reads public.notifications. Those rows are
// created by triggers on real order and deposit state changes, so an empty
// inbox means "nothing happened yet", not "the feature is broken".
//
// No polling timer: the page loads once, offers "Muat ulang", and marks rows
// read through explicit POSTs (idempotent, scoped to the session's user).
// ============================================================================
import { el, Badge, Button, Card, EmptyState, Skeleton, Alert, toast, PageHeader } from '../ui.js';
import { icon } from '../icons.js';
import { formatDate, timeAgo } from '../store.js';

const SEVERITY_TONE = { info: 'neutral', success: 'success', warning: 'warning', danger: 'danger' };
const SEVERITY_ICON = { info: 'info', success: 'check', warning: 'alert', danger: 'alert' };
const PER_PAGE = 20;

const targetFor = (item) => {
  if (item.orderId) return '/orders';
  if (item.depositId) return '/wallet';
  return null;
};

export default async function notificationsPage(ctx) {
  const { api, store, navigate, layout } = ctx;
  const { appShell } = await import('./_app-shell.js');

  const state = { items: [], page: 1, pages: 1, unreadCount: 0, total: 0, unreadOnly: false, loading: true, error: null };

  const listArea = el('div', { class: 'stack' });
  const summaryArea = el('div', { class: 'row row--between row--wrap' });
  const errorArea = el('div');

  const setUnreadBadge = (count) => {
    store.set({ unreadNotifications: Number(count) || 0 });
  };

  const card = (item) => {
    const tone = SEVERITY_TONE[item.severity] || 'neutral';
    const target = targetFor(item);
    const actions = el('div', { class: 'row', style: { gap: '8px' } });

    if (!item.readAt) {
      actions.appendChild(
        Button({
          variant: 'ghost',
          size: 'sm',
          iconName: 'check',
          children: 'Tandai dibaca',
          onClick: async () => {
            try {
              const result = await api.post('/api/notifications/read', { ids: [item.id] });
              item.readAt = new Date().toISOString();
              setUnreadBadge(result.unreadCount);
              render();
            } catch (err) {
              toast({ type: 'error', title: 'Gagal menandai', message: err?.message || 'Coba lagi.' });
            }
          }
        })
      );
    }

    if (target) {
      actions.appendChild(
        Button({
          variant: 'outline',
          size: 'sm',
          iconRight: 'arrowRight',
          children: 'Buka',
          onClick: () => {
            // Opening the subject marks the row read — a notification the user
            // already followed should not keep a badge alive.
            if (!item.readAt) {
              api.post('/api/notifications/read', { ids: [item.id] })
                .then((result) => setUnreadBadge(result.unreadCount))
                .catch(() => {});
            }
            navigate(target);
          }
        })
      );
    }

    return el('article', { class: `notif${item.readAt ? '' : ' notif--unread'}` },
      el('span', { class: `notif__icon notif__icon--${tone}` }, icon(SEVERITY_ICON[item.severity] || 'info', { size: 16 })),
      el('div', { class: 'notif__body' },
        el('div', { class: 'row row--between row--wrap', style: { gap: '8px' } },
          el('strong', { class: 'notif__title', text: item.title }),
          Badge({ tone, dot: true, children: item.severity === 'danger' ? 'Perlu perhatian' : item.severity === 'warning' ? 'Informasi' : 'Info' })
        ),
        item.body ? el('p', { class: 'notif__text', text: item.body }) : null,
        el('p', { class: 'notif__meta text-xs text-dim' },
          el('span', { attrs: { title: formatDate(item.createdAt) }, text: timeAgo(item.createdAt) }),
          item.readAt ? el('span', { text: ' · sudah dibaca' }) : el('span', { class: 'notif__dot', attrs: { 'aria-label': 'belum dibaca' } })
        ),
        actions
      )
    );
  };

  const load = async ({ append = false } = {}) => {
    state.loading = !append;
    if (!append) render();
    try {
      const query = new URLSearchParams({ page: String(state.page), per_page: String(PER_PAGE) });
      if (state.unreadOnly) query.set('unread', '1');
      const data = await api.get(`/api/notifications?${query.toString()}`);
      state.items = append ? [...state.items, ...data.notifications] : data.notifications;
      state.pages = data.pagination?.pages || 1;
      state.total = data.pagination?.total ?? data.total ?? state.items.length;
      state.unreadCount = data.unreadCount ?? 0;
      state.error = null;
      setUnreadBadge(state.unreadCount);
    } catch (err) {
      state.error = err?.message || 'Kotak notifikasi tidak dapat dimuat.';
    } finally {
      state.loading = false;
      render();
    }
  };

  const markAll = async () => {
    try {
      const result = await api.post('/api/notifications/read-all', {});
      if (result.updated > 0) {
        const now = new Date().toISOString();
        state.items = state.items.map((item) => ({ ...item, readAt: item.readAt || now }));
        toast({ type: 'success', title: 'Selesai', message: result.message });
      } else {
        toast({ type: 'info', title: 'Tidak ada yang baru', message: 'Semua notifikasi sudah dibaca.' });
      }
      setUnreadBadge(result.unreadCount ?? 0);
      state.unreadCount = result.unreadCount ?? 0;
      render();
    } catch (err) {
      toast({ type: 'error', title: 'Gagal', message: err?.message || 'Coba lagi.' });
    }
  };

  const render = () => {
    summaryArea.replaceChildren(
      el('div', { class: 'row', style: { gap: '8px' } },
        Badge({
          tone: state.unreadCount > 0 ? 'brand' : 'neutral',
          dot: state.unreadCount > 0,
          children: state.unreadCount > 0 ? `${state.unreadCount} belum dibaca` : 'Semua terbaca'
        }),
        el('span', { class: 'text-xs text-dim', text: `${state.total} notifikasi tersimpan` })
      ),
      el('div', { class: 'row', style: { gap: '8px' } },
        Button({
          variant: state.unreadOnly ? 'primary' : 'outline',
          size: 'sm',
          iconName: 'filter',
          children: 'Hanya belum dibaca',
          onClick: () => {
            state.unreadOnly = !state.unreadOnly;
            state.page = 1;
            load();
          }
        }),
        Button({ variant: 'ghost', size: 'sm', iconName: 'refresh', children: 'Muat ulang', onClick: () => load() }),
        Button({ variant: 'outline', size: 'sm', iconName: 'check', children: 'Tandai semua', onClick: markAll })
      )
    );

    errorArea.replaceChildren(
      state.error
        ? Alert({ tone: 'danger', title: 'Notifikasi tidak dapat dimuat', children: state.error })
        : el('span')
    );

    if (state.loading) {
      listArea.replaceChildren(Skeleton({ lines: 6 }), Skeleton({ lines: 3 }));
      return;
    }

    if (state.items.length === 0) {
      listArea.replaceChildren(
        el('div', { class: 'card' }, el('div', { class: 'card__body' },
          EmptyState({
            title: state.unreadOnly ? 'Tidak ada yang belum dibaca' : 'Belum ada notifikasi',
            description: state.unreadOnly
              ? 'Semua kabar terbaru sudah Anda baca.'
              : 'Notifikasi muncul di sini hanya setelah ada peristiwa nyata: order dibuat, nomor terbit, OTP masuk, order selesai, atau deposit ditinjau admin.',
            iconName: 'inbox'
          })
        ))
      );
      return;
    }

    const list = el('div', { class: 'stack notif-list' }, ...state.items.map(card));
    if (state.page < state.pages) {
      list.appendChild(
        Button({
          variant: 'outline',
          size: 'sm',
          iconName: 'chevronDown',
          children: `Muat ${state.items.length} berikutnya`,
          onClick: () => { state.page += 1; load({ append: true }); }
        })
      );
    }
    listArea.replaceChildren(list);
  };

  const content = el('div', { class: 'page animate-rise' },
    PageHeader({
      eyebrow: 'Kotak masuk',
      iconName: 'inbox',
      tone: 'info',
      title: 'Notifikasi',
      subtitle: 'Kabar dari peristiwa nyata di akun Anda — order, OTP, dan deposit. Tanpa pengingat karangan.'
    }),
    summaryArea,
    errorArea,
    listArea
  );

  render();
  await load();

  return {
    node: appShell(layout, 'notifications', content).shell,
    cleanup: () => {}
  };
}
